import * as chrono from "chrono-node";
import { extractExplicitEventTitle, pairedHonorees } from "./conversation-edits.ts";
import { conciergeCapabilityAnswer } from "./capabilities.ts";
import {
  classifyCreationBoundary,
  cleanCreationString,
  createCreationSessionId,
  deriveCreationStatus,
  getOutputRequirement,
  hasClearCreationSignal,
  isGreetingMessage,
  isMeaningfulEventText,
  normalizeCreationIntent,
  normalizeRequestedOutputs,
