      ...args.sourceContext,
      boundary: "envitefy_question",
    },
    eventPurpose: null,
    eventType: "unknown",
    title: null,
    ownership: "unknown",
    draftStatus: "needs_source_or_event",
    currentQuestion: null,
    canPersist: false,
    honoreeName: null,
    relationship: null,
    ageOrMilestone: null,
    ageOrMilestoneSkipped: null,
    dateText: null,
    timeText: null,
    startISO: null,
    endISO: null,
    timezone: DEFAULT_TIMEZONE,
    location: null,
    venue: null,
    additionalLocations: [],
    rsvpEnabled: null,
    rsvpDeadline: null,
    rsvpName: null,
    rsvpContact: null,
    numberOfGuests: null,
    registryLink: null,
    giftPreferenceNote: null,
    giftPromptDismissed: null,
    theme: null,
    tone: null,
